/**
 * gorilla — Chaos Gorilla for the estate: wholesale NODE/CELL loss.
 *
 * Chaos Monkey kills individual targets; Gorilla takes down an entire cell
 * (availability zone analog) at once to prove the fleet survives losing a
 * whole box. The estate's cells are the pitchfork host groups — a node, a pen
 * cell, or a port-range service group.
 *
 * Pure decision function + topology model, same shape as simian: injectable
 * RNG, deterministic seeds, no side effects.
 */
import { mulberry32 } from "@army/simian";

export interface Cell {
	id: string;
	/** Member target ids (daemons/processes/named resources) in this cell. */
	members: readonly string[];
	/** True for the "control-plane" cell that must always survive a single-cell loss. */
	critical?: boolean;
}

export interface CellTopology {
	cells: readonly Cell[];
}

export interface GorillaConfig {
	/** 0..1 chance a cell is taken down per pass (default 0.1 — Gorilla is rare). */
	probability: number;
	/** Exclude these cells from takedown entirely (never kill the control plane). */
	protect?: readonly string[];
	/** Business-hours guard (UTC). null = no guard. */
	window?: { start: number; end: number } | null;
}

export interface GorillaDecision {
	cell: Cell | null;
	down: string[]; // all member ids of the chosen cell
	roll: number;
	reason: string;
}

/** Choose a (non-critical, unprotected) cell to take down; null if none satisfy. */
export function chooseCell(topology: CellTopology, rng: () => number = mulberry32(42)): Cell {
	const eligible = topology.cells.filter(c => !c.critical);
	if (eligible.length === 0) throw new Error("gorilla: no eligible non-critical cells in topology");
	return eligible[Math.floor(rng() * eligible.length)]!;
}

/** The gorilla pass: with probability p, pick a cell and report its full loss. */
export function gorillaPass(
	topology: CellTopology,
	config: GorillaConfig,
	options: { rng?: () => number } = {},
): GorillaDecision {
	const rng = options.rng ?? mulberry32(42);
	const roll = rng();
	if (roll >= config.probability) {
		return { cell: null, down: [], roll, reason: `roll ${roll.toFixed(3)} ≥ p ${config.probability} — gorilla napping` };
	}
	const cell = chooseCell(topology, rng);
	const reason = cell.critical ? "critical cell (should be protected — topology error)" : `whole-cell loss ${cell.id}`;
	return { cell, down: [...cell.members], roll, reason };
}

/** Every member of every unprotected (non-critical) cell — the blast surface. */
export function blastSurface(topology: CellTopology): string[] {
	return topology.cells.flatMap(c => (c.critical ? [] : [...c.members]));
}